"""Builds pilot/LEDGER.csv (file, source URL, licence, attribution, what/how recorded, measured format) from the facts read off each source page on 2026-10-19
and pilot/MEASURED.json (written by analyze-pilot.mjs). Run: python build-ledger.py"""
import csv, hashlib, json, os, sys
HERE = os.path.dirname(os.path.abspath(__file__)); PILOT = os.path.normpath(os.path.join(HERE, '..', '..', 'pilot'))
